INSERT INTO company_info(id,payload,revision) VALUES(1,'{\"title\":\"Công ty TNHH Công nghệ Platinum\",\"slogan\":\"Tiên phong & Chất lượng\",\"intro\":\"Platinum Technology phát triển phần mềm và AI Agent giúp doanh nghiệp quản lý tập trung, tự động hóa công việc và phục vụ khách hàng tốt hơn.\",\"about\":\"Thành lập năm 2023, Platinum Technology được dẫn dắt bởi ông Trương Văn Trường — Giám đốc kiêm Nhà sáng lập với hơn 20 năm kinh nghiệm trong lĩnh vực công nghệ thông tin. Đội ngũ dưới 50 nhân sự làm chủ toàn bộ vòng đời sản phẩm: từ phân tích nghiệp vụ, thiết kế, lập trình đến triển khai, vận hành và bảo trì.\",\"vision\":\"Trở thành đối tác tin cậy hàng đầu trong lĩnh vực cung cấp giải pháp phần mềm cho doanh nghiệp, mang lại giá trị cao nhất cho khách hàng và góp phần vào sự phát triển bền vững của cộng đồng.\",\"mission\":\"Cung cấp các giải pháp phần mềm đột phá và tối ưu, phục vụ hiệu quả mục tiêu kinh doanh của khách hàng. Đặt lợi ích khách hàng lên hàng đầu và xây dựng quan hệ đối tác lâu dài, bền vững.\",\"ceo\":\"Trương Văn Trường\",\"tax\":\"3301719812\",\"founded\":\"2023\",\"phone\":\"0948 496 749\",\"email\":\"contact@platinumtechnology.net\",\"website\":\"www.platinumtechnology.net\",\"address\":\"Lô E1-28, Đường Số 2, KĐT Phú Mỹ An, P. An Cựu, TP Huế\",\"branch\":\"179 Trần Hưng Đạo, P. An Hải, TP Đà Nẵng\",\"logo\":\"\"}',1);
